const contactId = inputData.contactId;
const appointmentId = inputData.appointmentId;

const titleCase = str => str.replace(/\w\S*/g, word => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase());

const statusMap = {
  'noshow': 'No Show',
  'showed': 'Show',
  'cancelled': 'Canceled'
};

const formatStatus = str => statusMap[str.toLowerCase()] || titleCase(str);

const response = await customRequest.get(
  `https://services.leadconnectorhq.com/contacts/${contactId}/appointments`,
  {
    headers: {
      'Authorization': 'Bearer pit-06383926-0745-4053-898a-f18b22eee3e8',
      'Version': '2021-07-28',
      'Accept': 'application/json'
    }
  }
);

const events = response.data.events;
const appointment = events.find(e => e.id === appointmentId);

if (!appointment) {
  output = { error: 'Appointment not found', appointmentId };
} else {
  output = {
    appointmentId: appointment.id,
    contactId: appointment.contactId,
    calendarId: appointment.calendarId,
    assignedUserId: appointment.assignedUserId,
    appointmentStatus: formatStatus(appointment.appointmentStatus),
    startTime: appointment.startTime,
    endTime: appointment.endTime,
    title: appointment.title,
    notes: appointment.notes,
    address: appointment.address,
    dateAdded: appointment.dateAdded,
    dateUpdated: appointment.dateUpdated
  };
}
